-- =============================================================================
-- 9. ÍNDICES
-- =============================================================================
-- Los que llevan WHERE son PARCIALES: sólo indexan las filas que cumplen la
-- condición. Es lo que convierte "una sola en toda su vida" en "una sola VIGENTE
-- a la vez" — sin el WHERE serían absurdos, porque el historial también cuenta.
--
-- IMPORTANTE: los índices parciales dependen de que la columna de estado sea
-- NOT NULL. Una fila con estado nulo no cumple la condición del WHERE, así que
-- queda FUERA del índice y convive con una activa sin disparar conflicto. Por eso
-- las ocho columnas de estado del esquema son obligatorias.

-- --- Contacto ---
CREATE INDEX contacto_emergencia_persona_idx ON "Contacto_Emergencia" (id_persona);

-- --- Socio ---
CREATE UNIQUE INDEX "Registro_Salud_id_socio_fecha_idx" ON "Registro_Salud" (id_socio, fecha);

