CREATE UNIQUE INDEX membresia_una_activa_uidx ON "Membresia" (id_socio)
    WHERE (estado = 'ACTIVA'::estado_membresia);
COMMENT ON INDEX membresia_una_activa_uidx IS
'Una sola membresia ACTIVA por socio. Parcial a proposito: el historial de
renovaciones (VENCIDA / CANCELADA) no cuenta.';

CREATE INDEX congelamiento_origen_idx ON "Congelamiento" (origen, fecha_inicio);
