-- =============================================================================
-- 10. FUNCIONES Y TRIGGERS
-- =============================================================================
-- Son triggers y no CHECK porque un CHECK sólo puede mirar la fila que se está
-- escribiendo, y estas reglas necesitan contar o consultar filas de OTRA tabla.
--
-- Todos son CONSTRAINT TRIGGER DIFERIDOS: validan al COMMIT y no al INSERT. Eso
-- permite operaciones de varios pasos dentro de una transacción — dar de alta un
-- Empleado y después su subtipo, o cancelar una reserva y promover a alguien de
-- la lista de espera — sin que la validación se dispare a mitad de camino sobre
-- un estado intermedio que todavía no es el final.

-- -----------------------------------------------------------------------------
-- 10.1 · Ningún empleado sin subtipo
-- -----------------------------------------------------------------------------
CREATE FUNCTION trg_empleado_debe_tener_subtipo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_id_empleado int;
  v_existe      boolean;
  v_tiene       boolean;
BEGIN
  -- Empleado en riesgo de quedar colgado:
  --   INSERT en Empleado          -> NEW (el recién creado)
  --   DELETE/UPDATE en un subtipo -> OLD (el que perdió el rol)
  IF TG_TABLE_NAME = 'Empleado' THEN
    v_id_empleado := NEW.id_empleado;
  ELSE
    v_id_empleado := OLD.id_empleado;
  END IF;

  -- Si el empleado ya no existe (se borró en la misma tx), no exigimos nada.
  SELECT EXISTS(SELECT 1 FROM "Empleado" WHERE id_empleado = v_id_empleado)
    INTO v_existe;
  IF NOT v_existe THEN
    RETURN NULL;
  END IF;

  SELECT
       EXISTS(SELECT 1 FROM "Entrenador"    WHERE id_empleado = v_id_empleado)
    OR EXISTS(SELECT 1 FROM "Nutricionista" WHERE id_empleado = v_id_empleado)
    OR EXISTS(SELECT 1 FROM "Recepcionista" WHERE id_empleado = v_id_empleado)
    OR EXISTS(SELECT 1 FROM "Profesor"      WHERE id_empleado = v_id_empleado)
    INTO v_tiene;

  IF NOT v_tiene THEN
    RAISE EXCEPTION
      'Empleado % no tiene subtipo. Todo empleado debe ser al menos uno de: Entrenador, Nutricionista, Recepcionista o Profesor.',
      v_id_empleado
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_empleado_completo
    AFTER INSERT ON "Empleado"
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_empleado_debe_tener_subtipo();

CREATE CONSTRAINT TRIGGER trg_entrenador_no_deja_colgado
    AFTER DELETE OR UPDATE OF id_empleado ON "Entrenador"
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_empleado_debe_tener_subtipo();

CREATE CONSTRAINT TRIGGER trg_nutri_no_deja_colgado
    AFTER DELETE OR UPDATE OF id_empleado ON "Nutricionista"
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_empleado_debe_tener_subtipo();

CREATE CONSTRAINT TRIGGER trg_profesor_no_deja_colgado
    AFTER DELETE OR UPDATE OF id_empleado ON "Profesor"
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_empleado_debe_tener_subtipo();

CREATE CONSTRAINT TRIGGER trg_recep_no_deja_colgado
    AFTER DELETE OR UPDATE OF id_empleado ON "Recepcionista"
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_empleado_debe_tener_subtipo();


-- -----------------------------------------------------------------------------
-- 10.2 · No se vende más allá del cupo
-- -----------------------------------------------------------------------------
CREATE FUNCTION trg_reserva_respeta_cupo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cupo      int;
  v_ocupados  int;
  v_actividad text;
BEGIN
  -- EN_ESPERA y las canceladas no ocupan lugar: por definicion la lista de
  -- espera existe para los que NO entraron. Si contaran, el turno se veria
  -- lleno con gente que no tiene lugar y la cola nunca avanzaria.
  IF NEW.estado IS DISTINCT FROM 'RESERVADA' THEN
    RETURN NULL;
  END IF;

  SELECT t.cupo_maximo, a.nombre
    INTO v_cupo, v_actividad
  FROM "Turno" t
  LEFT JOIN "Actividad" a ON a.id_actividad = t.id_actividad
  WHERE t.id_turno = NEW.id_turno;

  -- El turno pudo haberse borrado en la misma transaccion. No es asunto de
  -- este trigger: de eso se ocupa la foreign key.
  IF v_cupo IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT count(*) INTO v_ocupados
  FROM "Reserva"
  WHERE id_turno = NEW.id_turno AND estado = 'RESERVADA';

  IF v_ocupados > v_cupo THEN
    RAISE EXCEPTION
      'El turno % (%) tiene cupo % y ya hay % reservas confirmadas.',
      NEW.id_turno, coalesce(v_actividad, 'sin actividad'), v_cupo, v_ocupados
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_reserva_cupo
    AFTER INSERT OR UPDATE OF estado, id_turno ON "Reserva"
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_reserva_respeta_cupo();


-- -----------------------------------------------------------------------------
-- 10.3 · No bajar el cupo por debajo de lo ya reservado
-- -----------------------------------------------------------------------------
CREATE FUNCTION trg_turno_cupo_no_menor_a_reservas() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ocupados int;
BEGIN
  SELECT count(*) INTO v_ocupados
  FROM "Reserva"
  WHERE id_turno = NEW.id_turno AND estado = 'RESERVADA';

  IF v_ocupados > NEW.cupo_maximo THEN
    RAISE EXCEPTION
      'No se puede dejar el cupo del turno % en %: ya hay % personas anotadas.',
      NEW.id_turno, NEW.cupo_maximo, v_ocupados
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_turno_cupo
    AFTER UPDATE OF cupo_maximo ON "Turno"
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_turno_cupo_no_menor_a_reservas();


-- -----------------------------------------------------------------------------
-- 10.4 · La inscripción usada tiene que corresponder [NUEVO]
-- -----------------------------------------------------------------------------
-- Cierra dos agujeros que estaban abiertos en Reserva:
--   1. Una inscripción a Yoga permitía reservar un turno de Boxeo.
--   2. Un socio podía consumir la inscripción de otro.
--
-- POR QUÉ UN TRIGGER Y NO UNA CLAVE FORÁNEA COMPUESTA. La alternativa era
-- propagar id_actividad hasta Reserva y atarla por los dos lados, que es la
-- técnica de fk_turno_profesor_habilitado. Se descartó para no agregar columnas:
-- la tabla queda exactamente como estaba.
--
-- LO QUE SE PIERDE CON ESTA ELECCIÓN, y conviene tenerlo presente: este trigger
-- vive en Reserva, así que sólo se dispara cuando se escribe una Reserva. Si más
-- adelante alguien cambia Plan_Actividad.id_actividad de un plan que ya tiene
-- inscripciones con reservas hechas, esas reservas quedan incoherentes y nada las
-- detecta. Una FK compuesta sí lo habría cubierto, porque las claves foráneas se
-- verifican también desde el lado referenciado. Es el precio de no tocar la tabla,
-- y es un precio bajo: cambiar la actividad de un plan existente no es una
-- operación normal del negocio.
--
-- SI ALGÚN DÍA MOLESTA: la salida no es agregar columnas sino replicar el trigger
-- sobre Plan_Actividad, rechazando el cambio de id_actividad cuando el plan ya
-- tiene inscripciones con reservas.
CREATE FUNCTION trg_reserva_coherencia_inscripcion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_act_turno         int;
  v_act_inscripcion   int;
  v_socio_inscripcion int;
  v_nombre_turno      text;
  v_nombre_inscrip    text;
BEGIN
  -- Clase suelta: no hay inscripcion que validar, se paga y se entra.
  IF NEW.id_inscripcion IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT t.id_actividad, a.nombre
    INTO v_act_turno, v_nombre_turno
  FROM "Turno" t
  LEFT JOIN "Actividad" a ON a.id_actividad = t.id_actividad
  WHERE t.id_turno = NEW.id_turno;

  -- El turno o la inscripcion pudieron borrarse en la misma transaccion:
  -- de eso se ocupan las foreign keys, no este trigger.
  IF v_act_turno IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT pa.id_actividad, i.id_socio, a.nombre
    INTO v_act_inscripcion, v_socio_inscripcion, v_nombre_inscrip
  FROM "Inscripcion_Actividad" i
  JOIN "Plan_Actividad" pa ON pa.id_plan_actividad = i.id_plan_actividad
  LEFT JOIN "Actividad" a  ON a.id_actividad = pa.id_actividad
  WHERE i.id_inscripcion = NEW.id_inscripcion;

  IF v_act_inscripcion IS NULL THEN
    RETURN NULL;
  END IF;

  -- 1. Misma actividad.
  IF v_act_turno <> v_act_inscripcion THEN
    RAISE EXCEPTION
      'La inscripcion % es de % y el turno % es de %. Una inscripcion solo sirve para su propia actividad.',
      NEW.id_inscripcion, coalesce(v_nombre_inscrip, 'actividad ' || v_act_inscripcion),
      NEW.id_turno,       coalesce(v_nombre_turno,   'actividad ' || v_act_turno)
      USING ERRCODE = 'check_violation';
  END IF;

  -- 2. Mismo socio.
  IF v_socio_inscripcion <> NEW.id_socio THEN
    RAISE EXCEPTION
      'La inscripcion % pertenece al socio % y la reserva es del socio %. Nadie puede consumir la inscripcion de otro.',
      NEW.id_inscripcion, v_socio_inscripcion, NEW.id_socio
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_reserva_coherente
    AFTER INSERT OR UPDATE OF id_turno, id_inscripcion, id_socio ON "Reserva"
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION trg_reserva_coherencia_inscripcion();


-- =============================================================================
